            s33: { name: ' 普通人 ', description: ' 你是这个时代最普通的普通人，很难触及非凡' }}

      };

      const baseAttributes = {
          huo_li: 0,
          ling_xing: 0,
          ren_xing: 0,
          li_zhi: 0,
          min_jie: 0,
          xing_yun: 0
      };

      const gameState = {
        currentStep: 'difficulty',
        selectedDifficulty: null,
        totalPoints: 0,
        spentAttributePoints: {
          huo_li: 0,
          ling_xing: 0,
          ren_xing: 0,
          li_zhi: 0,
          min_jie: 0,
          xing_yun: 0
        },
        selectedTalents: [],
        customTalent: '',
        selectedCountry: null,
        selectedBackground: null,
        customBackground: '',
        selectedSequence: null,
        customSequence: '',
        selectedGender: null,
        spentBackgroundPoints: 0,
        selectedYear: GAME_DATA.timeConfig.default.year,
        selectedMonth: GAME_DATA.timeConfig.default.month,
        selectedDay: GAME_DATA.timeConfig.default.day,
        get spentPoints() {
           let attributeCost = 0;
           for (const key in this.spentAttributePoints) {
               const spent = this.spentAttributePoints[key];
               if (key === 'xing_yun') {
                   attributeCost += spent * 5;
               } else {
                   attributeCost += spent;
               }
           }
           const talentCost = this.selectedTalents.reduce((sum, talentId) => {
               return sum + (GAME_DATA.talents[talentId]?.cost || 0);
           }, 0);
           return attributeCost + talentCost;
        },
        get remainingPoints() {
          return this.totalPoints - this.spentPoints;
        },
        get finalAttributes() {
           const final = {};
           for (const key in baseAttributes) {
                const base = baseAttributes[key];
                const spent = this.spentAttributePoints[key] || 0;
                final[key] = base + spent;
           }
           return final;
        }
      };

      // --- 新增：读档功能相关函数 ---
      // 从 IndexedDB 读取新版存档（独立实现，不依赖外部AppStorage）
function getSavesFromStorage() {
  // 与清除缓存函数的配置完全对齐（关键！）
  const DB_NAME = 'SefirotCastleDB';
  const STORE_NAME = 'saveData';
  const STORAGE_NAMESPACE = 'SEFIROT_CASTLE_REVISION_'; // 命名空间（注意拼写正确）
  const SAVE_KEY = STORAGE_NAMESPACE + 'multi_save_data'; // 完整键名：命名空间+multi_save_data

  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME);

    request.onsuccess = (event) => {
      const db = event.target.result;
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);

      // 用完整键名读取数据
      const getRequest = store.get(SAVE_KEY);

      getRequest.onsuccess = () => {
  const savesData = getRequest.result; // 此时savesData是{key: "...", value: "..."}
  let parsedData = {};

  if (savesData && savesData.value) {
    // 真正的存档内容在value字段中（JSON字符串）
    try {
      parsedData = JSON.parse(savesData.value); // 解析value得到包含slot_xxx的对象
      //console.log('解析后的存档内容:', parsedData); // 应输出{slot_1761667187527: {...}, ...}
    } catch (e) {
      console.error('解析存档value失败:', e);
      parsedData = {};
    }
  } else {
    console.log('未找到有效的存档value字段');
  }

  db.close();
  resolve(parsedData); // 传入renderLoadSlots的是包含slot_xxx的对象
};

      getRequest.onerror = (err) => {
        db.close();
        console.error('读取存档键失败:', err);
        resolve({});
      };
    };

    request.onerror = (err) => {
      console.error('打开数据库失败:', err);
      resolve({});
    };

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
      db.close();
      resolve({});
    };
  });
}

      function renderLoadSlots(saves) {
        const container = document.getElementById('load-slots-container');
        if (!container) return;

        let manualHtml = '<h3>时间线存档</h3>';
        const manualSaveKeys = Object.keys(saves).filter(key => key.startsWith('slot_')).sort((a, b) => b.localeCompare(a));

        if (manualSaveKeys.length > 0) {
            manualSaveKeys.forEach(slotId => {
                manualHtml += renderSlot(saves[slotId], slotId);
            });
        } else {
            manualHtml += '<p style="text-align:center; color:#a09c91; font-size:12px;">没有找到任何时间线存档。</p>';
        }

        container.innerHTML = manualHtml;

        document.querySelectorAll('.btn-load-slot').forEach(button => {
            button.addEventListener('click', (e) => {
                const slotId = e.target.closest('.save-slot').dataset.slotId;
                if (confirm('确定要读取这条时间线吗？当前的开局设置将会丢失。')) {
                    performLoad(slotId);
                }
            });
        });
      }

      function renderSlot(saveData, slotId) {
        let html = `<div class="save-slot" data-slot-id="${slotId}">`;
        html += `<div class="save-slot-info">`;

        if (saveData && saveData.timeline_history) {
            const date = new Date(saveData.timestamp).toLocaleString('zh-CN');
            const lastEvent = saveData.timeline_history[saveData.timeline_history.length - 1];
            const summary = (lastEvent.message || '').replace(/<[^>]*>/g, '').replace(/[\n\r]+/g, ' ').trim();
            const saveName = saveData.save_name || `未命名书签`;
            html += `
                <div class="slot-name">${saveName}</div>
                <div class="slot-time">${date} - 共 ${saveData.timeline_history.length} 回合</div>
                <div class="slot-summary">${summary ? summary.substring(0, 40) + '...' : '无正文记录'}</div>
            `;
        } else {
            // 此分支在新的逻辑下基本不会被触发
            html += `
                <div class="slot-name">无效或空存档</div>
                <div class="slot-time" style="font-style: italic; color: #a09c91;">存档数据不完整</div>
            `;
        }

        html += `</div><div class="save-slot-actions">`;
        html += `<button class="start-btn btn-load-slot" ${!saveData ? 'disabled' : ''}>读取</button>`;
        html += `</div></div>`;
        return html;
      }

      async function showLoadModal() {
        const modal = document.getElementById('load-modal');
        if (!modal) return;

        try {
          // 等待 IndexedDB 读取完成，拿到实际存档数据
          const allSaves = await getSavesFromStorage(); 
          //console.log('从IndexedDB读取的存档数据：', allSaves);
          // 渲染存档列表槽
          renderLoadSlots(allSaves); 
          modal.style.display = 'flex';
        } catch (error) {
          console.error('显示存档列表失败:', error);
          alert('无法加载存档列表时出错，请重试');
        }
      }

      async function performLoad(slotId) {
    document.getElementById('loading-overlay').style.display = 'flex';
    try {
        const allSaves = await getSavesFromStorage();
        const saveData = allSaves[slotId];

        if (!saveData || !saveData.timeline_history || saveData.timeline_history.length === 0) {
            throw new Error('时间线存档无效或已损坏');
        }

        // 1. 写入主UI读取的历史记录（备用键，与主UI加载逻辑完全对齐）
        const historyKey = STORAGE_NAMESPACE + 'frontend_chat_history_fallback';
        localStorage.setItem(historyKey, JSON.stringify(saveData.timeline_history));

        // 2. 同步`message0`触发正则+变量管理器（核心！彻底替代chatId依赖）
        const messages = await TavernHelper.getChatMessages('0') || [];
        let messageZero = messages[0] || {
            message_id: 'message0',
            message: '',
            is_user: false,
            role: 'assistant',
            data: {},
            timestamp: Date.now()
        };

        // 同步带正则标签的最新消息 → 触发正文正则，更新编辑栏
        const latestMessage = saveData.timeline_history.at(-1)?.message || '';
        messageZero.message = latestMessage;

        // 同步变量数据 → 变量管理器读取`data`更新属性状态
        messageZero.data = {
            ...saveData.snapshot_data, // 包含stat_data、equipped_items等核心变量
            timestamp: Date.now()
        };

        await TavernHelper.setChatMessages([messageZero], { 
            refresh: 'all',  
        });

        // 3. 恢复Gacha数据（确保抽卡模块状态一致）
        if (saveData.snapshot_data?.gacha_data) {
            localStorage.setItem(STORAGE_NAMESPACE + 'gacha_state', JSON.stringify(saveData.snapshot_data.gacha_data.state));
            localStorage.setItem(STORAGE_NAMESPACE + 'gacha_collection', JSON.stringify(saveData.snapshot_data.gacha_data.collection));
            localStorage.setItem(STORAGE_NAMESPACE + 'gacha_history', JSON.stringify(saveData.snapshot_data.gacha_data.history));
        }

        // 4. 兜底刷新（因开局正则无法调用内部加载方法，刷新确保所有逻辑生效）
        if (window.TavernHelper?.eventEmitter) {
            window.TavernHelper.eventEmitter.emit('CHAT_MESSAGES_UPDATED', {
                range: '0' // 仅刷新第0条消息的范围
            });
            console.log('[读档] 已触发对话内容刷新事件');
        }
        window.location.reload();

    } catch (error) {
        console.error('读档失败:', error);
        alert(`读档失败: ${error.message}`);
    } finally {
        document.getElementById('loading-overlay').style.display = 'none';
    }
}

