  clearCacheBtn.addEventListener('click', async () => { 
  if (!confirm('确定清除本地缓存吗？仅删除游戏相关数据，页面将刷新！')) {
    return;
  }

  // 🔴 第一步：先弹提示，告知用户开始清理
  alert('开始清理缓存...\n1. 清除本地存储数据\n2. 删除游戏数据库\n3. 重新加载页面');

  const clearIndexedDB = async () => {
    const DB_NAME = 'SefirotCastleDB';
    return new Promise((resolve, reject) => {
      const request = indexedDB.deleteDatabase(DB_NAME);

      request.onsuccess = () => {
        console.log(`[清理] 数据库 ${DB_NAME} 已彻底删除`);
        // 🔴 数据库删除成功，弹提示
        alert('✅ 数据库删除成功！');
        resolve(true);
      };

      request.onerror = (err) => {
        console.error(`[清理] 删除数据库失败:`, err);
        // 🔴 数据库删除失败，弹提示（不阻断流程）
        alert('⚠️ 数据库删除失败（浏览器限制），但本地缓存已清理');
        resolve(false);
      };

      request.onblocked = () => {
        alert('❌ 数据库被占用，请关闭所有游戏标签页后重试！');
        reject(new Error('数据库被占用，无法删除'));
      };
    });
  };

  try {
    const STORAGE_NAMESPACE = 'SEFIROT_CASTLE_REVISION_';
    const keysToDelete = [];
    const zeroMessageKey = 'tavern_chat_0';

    // 1. 清除localStorage
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key.startsWith(STORAGE_NAMESPACE) || key === 'multi_save_data') {
        keysToDelete.push(key);
      }
    }
    keysToDelete.forEach(key => localStorage.removeItem(key));
    localStorage.removeItem('frontend_chat_history_fallback');
    localStorage.removeItem(zeroMessageKey);

    // 🔴 localStorage清理完成，弹提示（告知删除数量）
    alert(`✅ 本地缓存清理完成！\n共删除 ${keysToDelete.length} 条数据`);

    // 2. 清理IndexedDB（等待完成后再继续）
    console.log('开始删除整个数据库...');
    await clearIndexedDB();

    // 🔴 所有清理完成，弹提示告知即将刷新
    alert('✅ 所有缓存清理完成！\n即将重新加载页面，请稍候...');

    // 🔴 优化刷新：延迟200ms再刷新，让提示有时间显示（避免刷新中断alert）
    setTimeout(() => {
      location.reload(true);
    }, 100);

  } catch (error) {
    console.error('清除失败:', error);
    // 🔴 异常时弹提示，告知用户失败原因
    alert(`❌ 清理失败：${error.message}\n请关闭页面重新尝试`);
  }
});

