        function renderTimeSelection() {
  // 计算当月最大天数（处理2月/30天月/31天月）
  const isLeapYear = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const getMaxDay = (year, month) => {
    if (year === GAME_DATA.timeConfig.maxYear && month === GAME_DATA.timeConfig.maxMonth) {
      return GAME_DATA.timeConfig.maxDay; // 1352年5月固定31天
    }
    const monthDays = [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    return monthDays[month - 1];
  };
  const maxDay = getMaxDay(gameState.selectedYear, gameState.selectedMonth);

  // 生成年份选项
  const yearOptions = [];
  for (let y = GAME_DATA.timeConfig.minYear; y <= GAME_DATA.timeConfig.maxYear; y++) {
    yearOptions.push(`<option value="${y}" ${gameState.selectedYear === y ? 'selected' : ''}>${y}年</option>`);
  }

  // 生成月份选项（1352年最多到5月）
  const monthOptions = [];
  const maxMonth = gameState.selectedYear === GAME_DATA.timeConfig.maxYear 
    ? GAME_DATA.timeConfig.maxMonth 
    : 12;
  for (let m = 1; m <= maxMonth; m++) {
    monthOptions.push(`<option value="${m}" ${gameState.selectedMonth === m ? 'selected' : ''}>${m}月</option>`);
  }

  // 生成日期选项
  const dayOptions = [];
  for (let d = 1; d <= maxDay; d++) {
    dayOptions.push(`<option value="${d}" ${gameState.selectedDay === d ? 'selected' : ''}>${d}日</option>`);
  }

  return `
    <div id="points-tracker">剩余点数: ${gameState.remainingPoints}</div>
    <div class="form-section">
      <label>第七步：选择开幕时间</label>
      <div class="time-selection" style="display: flex; gap: 10px; align-items: center; margin: 15px 0;">
        <select id="year-select" class="time-select">${yearOptions.join('')}</select>
        <select id="month-select" class="time-select">${monthOptions.join('')}</select>
        <select id="day-select" class="time-select">${dayOptions.join('')}</select>
      </div>
      <p style="color: #d8c8b0; font-size: 12px; margin: 5px 0; padding: 5px; background: rgba(15,10,5,0.5);">
        ${GAME_DATA.timeConfig.warning}
      </p>
    </div>
    <button type="button" id="prev-step-btn" class="generate-btn">返回</button>
    <button type="button" id="generate-startup-btn" class="generate-btn">生成人物</button>
  `;
}

        function bindEvents() {
            document.querySelectorAll('.difficulty-card').forEach(card => {
                card.addEventListener('click', () => {
                    const id = card.dataset.difficultyId;
                    if (gameState.selectedDifficulty !== id) {
                       gameState.selectedDifficulty = id;
                       gameState.totalPoints = GAME_DATA.difficulties[id].points;
                       for (const attr in gameState.spentAttributePoints) {
                           gameState.spentAttributePoints[attr] = 0;
                       }
                       gameState.selectedTalents = [];
                       gameState.customTalent = '';
                       gameState.selectedBackground = null;
                       gameState.customBackground = '';
                       gameState.selectedSequence = null;
                       gameState.customSequence = '';
                       gameState.selectedGender = null;
                    }
                    gameState.currentStep = 'attributes';
                    renderUI();
                });
            });

            document.querySelectorAll('.value-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    const attrId = btn.dataset.attribute;
                    const cost = attrId === 'xing_yun' ? 5 : 1;
                    if (btn.classList.contains('increase-btn')) {
                        if (gameState.remainingPoints >= cost) {
                            gameState.spentAttributePoints[attrId]++;
                        }
                    } else if (btn.classList.contains('decrease-btn')) {
                        if (gameState.spentAttributePoints[attrId] > 0) {
                            gameState.spentAttributePoints[attrId]--;
                        }
                    }
                    renderUI();
                });
            });

            document.querySelectorAll('.value-input').forEach(input => {
                input.addEventListener('change', (e) => {
                    const attrId = e.target.dataset.attribute;
                    const baseValue = baseAttributes[attrId];
                    const a_cost = attrId === 'xing_yun' ? 5 : 1;
                    const currentValue = baseValue + gameState.spentAttributePoints[attrId];
                    const targetValue = parseInt(e.target.value, 10);

                    if (isNaN(targetValue) || targetValue < baseValue) {
                        renderUI();
                        return;
                    }

                    const pointsDifference = (targetValue - currentValue) * a_cost;

                    if (pointsDifference <= gameState.remainingPoints) {
                        gameState.spentAttributePoints[attrId] += (targetValue - currentValue);
                    } 
                    renderUI();
                });
            });

            document.querySelectorAll('.talent-card').forEach(card => {
                if (!card.dataset.talentId) return;
                card.addEventListener('click', () => {
                    if (card.classList.contains('disabled')) return;
                    const id = card.dataset.talentId;
                    const index = gameState.selectedTalents.indexOf(id);
                    if (index > -1) {
                        gameState.selectedTalents.splice(index, 1);
                    } else {
                        gameState.selectedTalents.push(id);
                    }
                    renderUI();
