    function bindTimeEvents() {
  const yearSelect = document.getElementById('year-select');
  const monthSelect = document.getElementById('month-select');
  const daySelect = document.getElementById('day-select');
  if (!yearSelect || !monthSelect || !daySelect) return;

  const updateTimeOptions = () => {
    const selectedYear = parseInt(yearSelect.value);
    const selectedMonth = parseInt(monthSelect.value);
    // 更新月份选项（1352年限制到5月）
    monthSelect.innerHTML = '';
    const maxMonth = selectedYear === GAME_DATA.timeConfig.maxYear 
      ? GAME_DATA.timeConfig.maxMonth 
      : 12;
    for (let m = 1; m <= maxMonth; m++) {
      const option = document.createElement('option');
      option.value = m;
      option.textContent = `${m}月`;
      if (m === gameState.selectedMonth) option.selected = true;
      monthSelect.appendChild(option);
    }
    // 更新日期选项（根据年月动态计算）
    const isLeapYear = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    const getMaxDay = (y, m) => {
      if (y === GAME_DATA.timeConfig.maxYear && m === GAME_DATA.timeConfig.maxMonth) {
        return GAME_DATA.timeConfig.maxDay;
      }
      const monthDays = [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
      return monthDays[m - 1];
    };
    const maxDay = getMaxDay(selectedYear, selectedMonth);
    daySelect.innerHTML = '';
    for (let d = 1; d <= maxDay; d++) {
      const option = document.createElement('option');
      option.value = d;
      option.textContent = `${d}日`;
      if (d === gameState.selectedDay) option.selected = true;
      daySelect.appendChild(option);
    }
    // 保存选择
    gameState.selectedYear = selectedYear;
    gameState.selectedMonth = selectedMonth;
    gameState.selectedDay = Math.min(gameState.selectedDay, maxDay); // 防止日期超出当月最大天数
  };

  yearSelect.addEventListener('change', updateTimeOptions);
  monthSelect.addEventListener('change', updateTimeOptions);
  daySelect.addEventListener('change', () => {
    gameState.selectedDay = parseInt(daySelect.value);
  });
}

     function showLoadSetupModal() {
    const savedStateJSON = localStorage.getItem('lastLotMSetup');
    if (!savedStateJSON) {
        alert('没有找到上次的设定。');
        return;
    }
    const savedState = JSON.parse(savedStateJSON);

    const modal = document.getElementById('load-setup-modal');
    const modalBody = document.getElementById('load-setup-modal-body');
    const closeBtn = modal.querySelector('.modal-close-btn');

    let difficultyOptions = Object.entries(GAME_DATA.difficulties).map(([id, diff]) => 
        `<option value="${id}" ${savedState.selectedDifficulty === id ? 'selected' : ''}>${diff.name} (${diff.points}点)</option>`).join('');
    let countryOptions = Object.entries(GAME_DATA.countries).map(([id, country]) =>
        `<option value="${id}" ${savedState.selectedCountry === id ? 'selected' : ''}>${country.name}</option>`).join('');
    let backgroundOptions = Object.entries(GAME_DATA.backgrounds).map(([id, bg]) => 
        `<option value="${id}" ${savedState.selectedBackground === id ? 'selected' : ''}>${bg.name}</option>`).join('');
    let sequenceOptions = Object.entries(GAME_DATA.sequences).map(([id, seq]) => 
        `<option value="${id}" ${savedState.selectedSequence === id ? 'selected' : ''}>${seq.name}</option>`).join('');

    // 1. 先构建基础内容（不含按钮）
    let modalContent = `
        <div style="display: flex; flex-direction: column; gap: 15px; padding: 10px; font-size: 1rem;">
            <p>这是您上次的开局设定，您可以修改后直接开始。</p>
            <div><label>难度: </label><select id="setup-difficulty" style="width: 60%;">${difficultyOptions}</select></div>
            <div><label>地区: </label><select id="setup-country" style="width: 60%;">${countryOptions}</select></div>
            <div><label>出身: </label><select id="setup-background" style="width: 60%;">${backgroundOptions}</select></div>
            <div><label>途径: </label><select id="setup-sequence" style="width: 60%;">${sequenceOptions}</select></div>
            <div><label>自定义天赋: </label><input id="setup-custom-talent" type="text" value="${savedState.customTalent || ''}" style="width: 60%;"></div>
    `;

    // 2. 生成时间选择选项并添加到内容中（放在按钮前面）
    const isLeapYear = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    const getMaxDay = (y, m) => {
        if (y === GAME_DATA.timeConfig.maxYear && m === GAME_DATA.timeConfig.maxMonth) return 31;
        const monthDays = [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        return monthDays[m - 1];
    };
    const savedYear = savedState.selectedYear || 1349;
    const savedMonth = savedState.selectedMonth || 1;
    const savedDay = savedState.selectedDay || 1;
    const maxDay = getMaxDay(savedYear, savedMonth);

    // 年份选项
    const yearOptions = [];
    for (let y = 1349; y <= 1352; y++) {
        yearOptions.push(`<option value="${y}" ${savedYear === y ? 'selected' : ''}>${y}年</option>`);
    }
    // 月份选项
    const maxMonth = savedYear === 1352 ? 5 : 12;
    const monthOptions = [];
    for (let m = 1; m <= maxMonth; m++) {
        monthOptions.push(`<option value="${m}" ${savedMonth === m ? 'selected' : ''}>${m}月</option>`);
    }
    // 日期选项
    const dayOptions = [];
    for (let d = 1; d <= maxDay; d++) {
        dayOptions.push(`<option value="${d}" ${savedDay === d ? 'selected' : ''}>${d}日</option>`);
    }

    // 追加时间选择到基础内容中（关键：在按钮之前）
    modalContent += `
        <div><label>开局时间: </label>
            <select id="setup-year" style="width: 25%;">${yearOptions.join('')}</select>
            <select id="setup-month" style="width: 25%;">${monthOptions.join('')}</select>
            <select id="setup-day" style="width: 25%;">${dayOptions.join('')}</select>
        </div>
    `;

    // 3. 最后添加确认按钮（放在时间选择后面）
    modalContent += `
            <div style="text-align: right; margin-top: 20px;">
                <button id="confirm-load-setup" class="start-btn" style="font-size: 1.2rem; padding: 10px 20px;">确认并开始</button>
            </div>
        </div>
    `;

    // 设置完整内容到弹窗
    modalBody.innerHTML = modalContent;

    // 绑定时间选择联动（保持不变）
    const setupYear = document.getElementById('setup-year');
    const setupMonth = document.getElementById('setup-month');
    const setupDay = document.getElementById('setup-day');
    setupYear.addEventListener('change', () => {
        const y = parseInt(setupYear.value);
        const maxM = y === 1352 ? 5 : 12;
        setupMonth.innerHTML = '';
        for (let m = 1; m <= maxM; m++) {
            const opt = document.createElement('option');
            opt.value = m;
            opt.textContent = `${m}月`;
            setupMonth.appendChild(opt);
        }
    });
    setupMonth.addEventListener('change', () => {
        const y = parseInt(setupYear.value);
        const m = parseInt(setupMonth.value);
        const maxD = getMaxDay(y, m);
        setupDay.innerHTML = '';
        for (let d = 1; d <= maxD; d++) {
            const opt = document.createElement('option');
            opt.value = d;
            opt.textContent = `${d}日`;
            setupDay.appendChild(opt);
        }
    });

    modal.style.display = 'flex';

    const confirmBtn = document.getElementById('confirm-load-setup');
    confirmBtn.addEventListener('click', async () => {
        // 从弹窗中读取修改后的值并更新gameState
        Object.assign(gameState, savedState); // 先恢复所有旧状态
        gameState.selectedDifficulty = document.getElementById('setup-difficulty').value;
        gameState.totalPoints = GAME_DATA.difficulties[gameState.selectedDifficulty].points;
        gameState.selectedCountry = document.getElementById('setup-country').value;
        gameState.selectedBackground = document.getElementById('setup-background').value;
        gameState.selectedSequence = document.getElementById('setup-sequence').value;
        gameState.customTalent = document.getElementById('setup-custom-talent').value;
        gameState.selectedYear = parseInt(setupYear.value);
        gameState.selectedMonth = parseInt(setupMonth.value);
        gameState.selectedDay = parseInt(setupDay.value);
        // 其他属性（如点数分配）保持上次的不变

        modal.style.display = 'none';
        showSetupUI();
        await generateStartup();
    });

    closeBtn.onclick = () => { modal.style.display = 'none'; };
}

