"name": "食材处理专精",
"description": "拥有出色的食材处理能力，擅长寻找食材薄弱处并运用切、剁、割等技术",
"type": "非凡能力"
}
],
"流浪汉途径-序列5 ": [
{
"name": "极广食谱范围",
"description": "食谱大幅拓宽，可食用并处理此前无法摄入的物质，包括一定程度的污染和火球、闪电等能量体",
"type": "被动特性"
},
{
"name": "临时能力剥夺",
"description": "可在一定时间内剥夺目标一到三种能力，限制目标战斗力",
"type": "非凡能力"
},
{
"name": "永久能力窃取",
"description": "剥夺能力后吃掉目标部分血肉，可永久性获得其中一种能力，目标则永久失去（可通过重喝魔药或对应剥夺者恢复）",
"type": "非凡能力"
}
],
"流浪汉途径-序列4": [
{
"name": "巨型生物形态",
"description": "转变为真正的庞然大物，体型适配海量进食需求",
"type": "被动特性"
},
{
"name": "海怪级生存基础",
"description": "拥有海怪层次的力量和生命力，生存与战斗底蕴深厚",
"type": "被动特性"
},
{
"name": "无失控的吞噬利用",
"description": "可直接吞噬非凡特性和神奇物品，通过消化、存储进行利用且不会失控，但会累积疯狂和食欲",
"type": "被动特性"
},
{
"name": "吞噬式攻击",
"description": "能以吞噬动作直接发起攻击，将目标纳入自身消化系统造成伤害",
"type": "非凡能力"
},
{
"name": "海量进食能力",
"description": "单次可摄入十几二十吨食物，满足能量与物质需求",
"type": "非凡能力"
}
],
"流浪汉途径-序列3 ": [
{
"name": "多首形态转化",
"description": "吞噬的非凡特性和神奇物品经消化吸收后，会演变为额外的身体和脑袋",
"type": "被动特性"
},
{
"name": "多重同步攻击",
"description": "能同时发起九种不同攻击，战斗方式多元且覆盖范围广",
"type": "非凡能力"
}
],
"流浪汉途径-序列2 ": [
{
"name": "权柄初步掌控",
"description": "初步掌握吞噬和消除权柄，具备影响规则与概念的基础能力",
"type": "神之权柄"
},
{
"name": "吞噬范围限制",
"description": "吞噬规则和概念有数量与范围限制，无法直接吞噬区域和实体目标，需先以漩涡吸入",
"type": "被动特性"
},
{
"name": "规则吞噬与运用",
"description": "吞噬一个规则可使用一次，吞掉本源性力量可无限次使用；被吞噬规则一到三分钟内自我修复且无法吐出",
"type": "非凡能力"
},
{
"name": "概念吞噬与抹消",
"description": "吞噬浅层次概念分可修复与永久消失两种方式，永久消失需其他非凡力量方可恢复",
"type": "非凡能力"
},
{
"name": "概念性抹消",
"description": "可抹消一些概念性的东西，直接作用于非实体层面",
"type": "非凡能力"
}
],
"流浪汉途径-序列1 ": [
{
"name": "极致消化抹除范围",
"description": "除旧日精神印记、唯一性、源质和非凡特性本身外，其余万物皆可消化抹除，包括自身大脑和智慧",
"type": "被动特性"
},
{
"name": "宇宙清扫者权柄",
"description": "消化与抹除能力是权柄的直接体现，承担 “宇宙清扫者” 的功能",
"type": "神之权柄"
},
{
"name": "万物消解能力",
"description": "可对目标进行彻底消化与抹除，清除存在痕迹",
"type": "非凡能力"
}
],
"流浪汉途径-序列0 ": [
{
"name": "核心权柄掌控",
"description": "完全掌控聚合和饥饿权柄，是途径力量的顶点体现",
"type": "神之权柄"
},
{
"name": "自噬与聚合本能",
"description": "时刻想吃掉一切，同时不断吞噬自身，追求极致聚合带来的饱腹感",
"type": "被动特性"
},
{
"name": "命运间接影响",
"description": "借助聚合权柄，无需对应消化能力即可在一定程度上影响命运",
"type": "非凡能力"
},
{
"name": "神话生物形态",
"description": "呈现为幽暗漩涡，内露白森森牙齿与包容所有颜色的混沌液体，形似抽象胃袋",
"type": "被动特性"
}
],
"萨满途径-序列9": [
{
"name": "灵界感应",
"description":"能感应到不同的空间和更高处的世界，并让精神初步接触。但这会导致灵魂被现实世界之外的怪物注意到，成为它们入侵的目标。一旦精神屏障被攻破，灵魂将被控制或取代。",
"type": "被动特性"
},
{
"name": "灵性借取",
"name": "通灵",
"description":"能选择一个区域，通过设置图腾、举行仪式将其固定为自身领地，进而沟通领地内的万物之灵借取力量施展法术。然而，该力量严格受限于领地，离开越远则衰退越快，且更换领地需要耗时约三天的复杂仪式。",
"type": "非凡能力"
}
],
"萨满途径-序列8": [
{
"name": "真实导向的感知本能",
"description": "本能趋向于触及、看见并阐述真实，对虚假信息有天然的排斥与辨识倾向",
"type": "被动特性"
},
{
"name": "超常速度",
"description": "具备远超普通人类的速度，可快速移动或完成信息采集等动作",
"type": "被动特性"
},
{
"name": "真实感知与阐述",
"description": "能够主动触及并看见事物的真实本质，且可清晰阐述所感知到的真实信息",
"type": "非凡能力"
}
],
"萨满途径-序列7": [
{
"name": "精神污染倾向",
"description": "从该序列开始逐渐出现精神问题，类似因受污染颜料影响而精神异常的画家",
"type": "被动特性"
},
{
"name": "真实具象化创作",
"description": "可将自己想要的真实描绘出来，使画作具备不同的非凡表现效果",
"type": "非凡能力"
},
{
"name": "预言性质赋予",
"description": "因曾触及、看见真实，画出的作品在某些时候带有一定的预言性质",
"type": "非凡能力"
}
],
"萨满途径-序列6": [
{
"name": "幻想偏好",
"description": "天生喜欢幻想，对虚构场景与概念有极强的敏感度和创造力",
"type": "被动特性"
},
{
"name": "幻想现实转化",
"description": "能在一定程度上将自身幻想转化为现实，实现虚构概念的实体化",
"type": "非凡能力"
}
],
"萨满途径-序列5": [
{
"name": "维度穿梭特性",
"description": "处于固定的异维度时，很难被现实世界的攻击伤害，但也缺乏影响现实的有效手段",
"type": "被动特性"
},
{
"name": "画中世界创造",
"description": "能真正创作出一个独立的画中世界，构建完整的虚构空间",
"type": "非凡能力"
},
{
"name": "维度奥秘初探与穿梭",
"description": "初步掌握维度的奥秘，可固定一个维度并自由出入该维度",
"type": "非凡能力"
}
],
"萨满途径-序列4 旅客": [
{
"name": "异维度存在本质",
"description": "成为另外一个维度的存在，本质与异次元、异时空、其他维度深度绑定",
"type": "被动特性"
},
{
"name": "维度掌控深化",
"description": "对维度的掌握更深入，以此展现出各种奇妙或恐怖的非凡能力",
"type": "非凡能力"
}
],
"萨满途径-序列3 弦之弹奏者": [
{
"name": "“弦” 掌控基础",
"description": "开始掌控 “弦” 这一核心媒介，与现实的底层规则建立连接",
"type": "被动特性"
},
{
"name": "弦动现实干涉",
"description": "通过弹奏 “弦” 来影响现实状态，改变现实的物理或规则层面属性",
"type": "非凡能力"
}
],
"萨满途径-序列2 维度之影": [
{
"name": "完整高维生物形态",
"description": "晋升为完整的高维生物，存在形式超越低维生物的认知",
"type": "被动特性"
},
{
"name": "维度自由操控",
"description": "可自由进行升维与降维操作，能自由利用不同维度的规则与空间特性",
"type": "非凡能力"
}
],
"萨满途径-序列1": [
{
"name": "观察干预本质",
"description": "观察行为本身会对观察对象产生决定性影响，是能力运作的核心逻辑",
"type": "被动特性"
},
{
"name": "观察导向结果",
"description": "观察方式会直接且关键地改变观察对象之后的发展轨迹与最终结果",
"type": "非凡能力"
}
],
"萨满途径-序列0": [
{
"name": "全知视野基础",
"description": "具备看到世间一切与命运变化的基础特质，视野覆盖范围无死角",
"type": "被动特性"
},
{
"name": "存在感知关联",
"description": "自身的观察与否会影响事物的存在状态，“看见时花开灿烂，不见时花与心同寂”",
"type": "被动特性"
},
{
"name": "全域洞察与命运观测",
"description": "能清晰看到世间所有事物的细节，精准观测命运的波动与变化",
"type": "神之权柄"
},
{
"name": "神话生物形态",
"description": "呈现为 “维度的影子”，形态抽象且与维度本质深度融合",
"type": "被动特性"
},
{
"name": "维度与幻想终极权柄",
"description": "全面掌控维度的所有规则，是一切幻想的源头，可创造无数画中世界，具备支配维度与幻想的至高权柄",
"type": "神之权柄"
}
]
}

